--
-- Name: master_training_dataset; Type: VIEW; Schema: public; Owner: admin
--

CREATE VIEW public.master_training_dataset AS
 SELECT m.date_mesure,
    m.parcelle_id,
    m.temp_moyenne,
    m.temp_min,
    m.temp_max,
    m.precipitations_mm,
    s.ndvi,
    s.ndwi
   FROM (public.donnees_meteo m
     LEFT JOIN public.indices_satellites s ON (((m.parcelle_id = s.parcelle_id) AND (m.date_mesure = s.date_capture))));


ALTER TABLE public.master_training_dataset OWNER TO admin;

